'use client';
const require_toggle_group = require("./toggle-group.cjs");
const require_toggle_group_item = require("./toggle-group-item.cjs");
//#region src/components/toggle-group/index.ts
/**
* Display a group of buttons that can be toggled between.
*
* @example
* <ToggleGroup aria-label="Label" onChange={(value) => console.log(value)}>
*   <ToggleGroup.Item value='1'>Toggle 1</ToggleGroup.Item>
*   <ToggleGroup.Item value='2'>Toggle 2</ToggleGroup.Item>
*   <ToggleGroup.Item value='3'>Toggle 3</ToggleGroup.Item>
* </ToggleGroup>
*/
const ToggleGroupComponent = Object.assign(require_toggle_group.ToggleGroup, { Item: require_toggle_group_item.ToggleGroupItem });
ToggleGroupComponent.Item.displayName = "ToggleGroup.Item";
//#endregion
exports.ToggleGroup = ToggleGroupComponent;
exports.ToggleGroupItem = require_toggle_group_item.ToggleGroupItem;
